Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Monthly Steam score per game, with major events marked and labelled on the line.",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "isValid(datum.score) && datum.reviews >= 300"
    },
    {
      "calculate": "toDate(datum.month + ''-01'')",
      "as": "month_date"
    },
    {
      "calculate": "isValid(datum.events) && datum.events != '''' ? datum.events : null",
      "as": "event_label"
    }
  ],
  "encoding": {
    "x": {
      "field": "month_date",
      "type": "temporal",
      "title": null,
      "axis": {
        "format": "%Y",
        "tickCount": "year",
        "domain": false,
        "ticks": false,
        "gridColor": "#EEEEEC",
        "labelColor": "#5F6368"
      }
    },
    "y": {
      "field": "score",
      "type": "quantitative",
      "title": null,
      "scale": {
        "zero": false
      },
      "axis": {
        "format": ".0%",
        "tickCount": 5,
        "domain": false,
        "ticks": false,
        "gridColor": "#EEEEEC",
        "labelColor": "#5F6368"
      }
    },
    "color": {
      "field": "game",
      "type": "nominal",
      "scale": {
        "domain": [
          "Cyberpunk 2077",
          "The Witcher 3"
        ],
        "range": [
          "#A87400",
          "#2F5D8C"
        ]
      },
      "legend": {
        "orient": "bottom",
        "title": null,
        "labelColor": "#5F6368",
        "symbolType": "stroke",
        "labelLimit": 240
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "line",
        "strokeWidth": 2,
        "interpolate": "linear"
      },
      "encoding": {
        "tooltip": [
          {
            "field": "game",
            "title": "Game"
          },
          {
            "field": "month_date",
            "type": "temporal",
            "title": "Month",
            "format": "%b %Y"
          },
          {
            "field": "score",
            "title": "Steam score",
            "format": ".1%"
          },
          {
            "field": "reviews",
            "title": "Reviews",
            "format": ","
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum.event_label != null"
        }
      ],
      "mark": {
        "type": "circle",
        "size": 70,
        "fill": "#FFFFFF",
        "strokeWidth": 2,
        "opacity": 1
      },
      "encoding": {
        "stroke": {
          "field": "game",
          "type": "nominal",
          "scale": {
            "domain": [
              "Cyberpunk 2077",
              "The Witcher 3"
            ],
            "range": [
              "#A87400",
              "#2F5D8C"
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "game",
            "title": "Game"
          },
          {
            "field": "month_date",
            "type": "temporal",
            "title": "Month",
            "format": "%b %Y"
          },
          {
            "field": "event_label",
            "title": "Major events"
          },
          {
            "field": "score",
            "title": "Steam score",
            "format": ".1%"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "datum.game === ''The Witcher 3''"
        },
        {
          "filter": "datum.event_label != null"
        },
        {
          "calculate": "utcyear(datum.month_date) * 12 + utcmonth(datum.month_date)",
          "as": "event_month_index"
        },
        {
          "window": [
            {
              "op": "lag",
              "field": "event_month_index",
              "as": "prev_event_month_index"
            }
          ],
          "groupby": [
            "game"
          ],
          "sort": [
            {
              "field": "month_date",
              "order": "ascending"
            }
          ]
        },
        {
          "filter": "!isValid(datum.prev_event_month_index) || datum.event_month_index - datum.prev_event_month_index >= 6"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "bottom",
        "angle": 325,
        "dx": 4,
        "dy": -6,
        "fontSize": 9,
        "limit": 170
      },
      "encoding": {
        "text": {
          "field": "event_label"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.game === ''Cyberpunk 2077''"
        },
        {
          "filter": "datum.event_label != null"
        },
        {
          "calculate": "utcyear(datum.month_date) * 12 + utcmonth(datum.month_date)",
          "as": "event_month_index"
        },
        {
          "window": [
            {
              "op": "lag",
              "field": "event_month_index",
              "as": "prev_event_month_index"
            }
          ],
          "groupby": [
            "game"
          ],
          "sort": [
            {
              "field": "month_date",
              "order": "ascending"
            }
          ]
        },
        {
          "filter": "!isValid(datum.prev_event_month_index) || datum.event_month_index - datum.prev_event_month_index >= 6"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "angle": 35,
        "dx": 4,
        "dy": 6,
        "fontSize": 9,
        "limit": 170
      },
      "encoding": {
        "text": {
          "field": "event_label"
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "background": null
  }
}'
